import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { StructuredListContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: StructuredListContract & { toolbarContent?:Snippet; actions?:Snippet<[import("@unofficial-krds/contracts").StructuredListItem]> } = $props();

